/** Asset import declarations used by this example's TypeScript sources. */
declare module '*.css';

declare module '*.json' {
  const value: unknown;
  export default value;
}

declare module '*.mp3' {
  const source: string;
  export default source;
}

declare module '*.m4a' {
  const source: string;
  export default source;
}

declare module '*.otf' {
  const source: string;
  export default source;
}

declare module '*.woff2' {
  const source: string;
  export default source;
}

declare module '*.png' {
  const source: string;
  export default source;
}

declare module '*.webp' {
  const source: string;
  export default source;
}

declare module '*.avif' {
  const source: string;
  export default source;
}

declare module '*.skel' {
  const source: string;
  export default source;
}

declare module '*.atlas' {
  const source: string;
  export default source;
}

declare module '*.glsl' {
  const source: string;
  export default source;
}
